// src/App.js
import React from "react";
import { Button, Typography, Container } from "@mui/material";

function App() {
  return (
    <Container>
      <Typography variant="h2" gutterBottom>
        Welcome to Visitor Management Dashboard
      </Typography>
      <Button variant="contained" color="primary">
        Get Started
      </Button>
    </Container>
  );
}

export default App;
